    showmover=false,
    boardfont=condal % Aesthetic font style for pieces
}

% Use the \chessboard command with the 'setfen' option
\chessboard[setfen=rnbqkbnr/pppp1ppp/8/4p3/4P3/8/PPPP1PPP/RNBQKBNR b KQkq - 0 1]

\end{document}
```

